#define R iResolution
#define T iTime
#define M iMouse

void mainImage(out vec4 fragColor, in vec2 fragCoord) {

  // uncomment each line, one by one, to test different origin locations for the coordinate system 
  vec2 origin = vec2(0.0, 0.0); // set default origin = lower-left window corner
  //vec2 origin = 0.5*R.xy; // set origin at window center
  //vec2 origin = M.xy; // set origin at mouse position
  //vec2 origin = R.xy*(0.5 + 0.4*vec2(cos(T), 0.8*sin(2.0*T))); // set moving origin

  vec2 pos = (fragCoord.xy - origin) / R.y; // use resolution-independent coordinates
  float freq = 12.0; ivec2 tile = ivec2(floor(pos * freq)); // convert position into tile coordinates
  ivec3 color[6] = ivec3[](ivec3(1,0,0), ivec3(0,1,0), ivec3(0,0,1),
    ivec3(0,1,1), ivec3(1,0,1), ivec3(1,1,0)); // generate colormap

  // uncomment each line, one by one, to test different patterns 
  ivec3 rgb = ivec3(max(abs(tile.x), abs(tile.y))); // single black tile
  //ivec3 rgb = ivec3(abs(tile.x + tile.y) % 2); // black-and-white chessboard
  //int n = abs(tile.x + tile.y) % 6; ivec3 rgb = color[n]; // multi-color chessboard
  //int n = max(abs(tile.x), abs(tile.y)) % 6; ivec3 rgb = color[n]; // concentric squares

  fragColor = vec4(vec3(rgb), 1.0); // set fragment color
}
